clc; clear
format short g

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Simple logit estimation using the data generated by C0_generate_data.m
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Step 0: Preliminaries
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

% Directories
project_dir = fileparts(mfilename('fullpath'));
repo_dir = fileparts(fileparts(project_dir));

addpath(fullfile(project_dir,'functions'));
[~, out_dir, log_dir] = set_data_path();

if ~exist(log_dir,'dir')
    mkdir(log_dir);
end

% Log all printed output while keeping it visible in the terminal
log_file = fullfile(log_dir,'C1_simple_logit_log.txt');
diary(log_file);
diary on

% Functions
addpath(genpath(fullfile(project_dir,'econometrics_toolbox')));
addpath(genpath(fullfile(project_dir,'functions')));

% Input and output files
data_file = fullfile(out_dir,'Data.mat');
result_file = fullfile(out_dir,'SimpleLogit.mat');


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Step 1: Load C0 Output
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

load(data_file, 'Cst', 'YMat', 'XMat')

% Dependent variable: simple-logit mean utility after absorbing brand-model FE
y = YMat.mean_utility_dm;

% Regressors: price and observed characteristics after absorbing brand-model FE
X = XMat.chars_dm;
X_names = XMat.chars_names;

% Instruments: excluded IVs plus exogenous characteristics, all demeaned
Z = XMat.IVall;
Z_names = XMat.IVall_names;


% For simple logit, exclude differentiation IVs whose names start with "lc"
%{
keep_iv = ~startsWith(string(Z_names), "lc");
Z = Z(:, keep_iv);
Z_names = Z_names(keep_iv);

%}
% Cluster at market level, as in C0_generate_data.m
cluster_id = Cst.mkt_index;


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Step 2: Simple Logit OLS
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

[ols_beta, ols_se, ols_tstat, ols_pval, ols_R2] = ols(y, X, cluster_id);

ols_table = make_result_table(X_names, ols_beta, ols_se, ols_tstat, ols_pval);

disp('Simple logit OLS results');
disp(ols_table)
fprintf('OLS adjusted R-squared: %.4f\n\n', ols_R2);


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Step 3: Simple Logit 2SLS
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

[tsls_beta, tsls_se, tsls_tstat, tsls_pval, tsls_R2] = iv_regress(y, X, Z, cluster_id);
tsls_resid = y - X*tsls_beta;

tsls_table = make_result_table(X_names, tsls_beta, tsls_se, tsls_tstat, tsls_pval);

disp('Simple logit 2SLS results');
disp(tsls_table)
fprintf('2SLS adjusted R-squared: %.4f\n\n', tsls_R2);


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Step 4: First-Stage Checks for Price
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

% In the C0 data structure, the first column of X is price_real. XMat.IVall
% contains excluded IVs and all exogenous characteristics.
price_dm = XMat.p_real_dm;

[fs_beta, fs_se, fs_tstat, fs_pval, fs_R2] = ols(price_dm, Z, cluster_id);

fs_table = make_result_table(Z_names, fs_beta, fs_se, fs_tstat, fs_pval);

disp('First-stage regression for price_real');
disp(fs_table)
fprintf('First-stage adjusted R-squared: %.4f\n\n', fs_R2);


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Step 5: Save Results
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

SimpleLogit.OLS.beta = ols_beta;
SimpleLogit.OLS.se = ols_se;
SimpleLogit.OLS.tstat = ols_tstat;
SimpleLogit.OLS.pval = ols_pval;
SimpleLogit.OLS.R2 = ols_R2;
SimpleLogit.OLS.table = ols_table;

SimpleLogit.TSLS.beta = tsls_beta;
SimpleLogit.TSLS.se = tsls_se;
SimpleLogit.TSLS.tstat = tsls_tstat;
SimpleLogit.TSLS.pval = tsls_pval;
SimpleLogit.TSLS.R2 = tsls_R2;
SimpleLogit.TSLS.resid = tsls_resid;
SimpleLogit.TSLS.table = tsls_table;

SimpleLogit.FirstStage.beta = fs_beta;
SimpleLogit.FirstStage.se = fs_se;
SimpleLogit.FirstStage.tstat = fs_tstat;
SimpleLogit.FirstStage.pval = fs_pval;
SimpleLogit.FirstStage.R2 = fs_R2;
SimpleLogit.FirstStage.table = fs_table;

SimpleLogit.X_names = X_names;
SimpleLogit.Z_names = Z_names;

save(result_file, 'SimpleLogit')

disp(['Simple logit results saved to: ', result_file]);

diary off


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Local Functions
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

function result_table = make_result_table(var_names, beta, se, tstat, pval)

    show = ~cellfun(@isempty, var_names(:));

    result_table = table(var_names(show)', round(beta(show),3), ...
        round(se(show),3), round(tstat(show),3), round(pval(show),3), ...
        'VariableNames', {'Variable','Estimate','StdErr','Tstat','Pval'});

end
